CREATE DATABASE IF NOT EXISTS online_course_management;
USE online_course_management;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,role ENUM("student","instructor","admin") DEFAULT "student",created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) UNIQUE NOT NULL,description TEXT);
CREATE TABLE IF NOT EXISTS courses(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200) NOT NULL,description TEXT,category_id INT,price DECIMAL(10,2) DEFAULT 0,level VARCHAR(30) DEFAULT "Beginner",status VARCHAR(20) DEFAULT "published",created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS enrollments(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,course_id INT NOT NULL,progress DECIMAL(5,2) DEFAULT 0,status VARCHAR(20) DEFAULT "active",enrolled_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(student_id,course_id),FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS lessons(id INT AUTO_INCREMENT PRIMARY KEY,course_id INT NOT NULL,title VARCHAR(200) NOT NULL,content TEXT,order_no INT DEFAULT 1,FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS quizzes(id INT AUTO_INCREMENT PRIMARY KEY,course_id INT NOT NULL,title VARCHAR(200) NOT NULL,pass_percentage INT DEFAULT 60,FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS certificates(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,course_id INT NOT NULL,certificate_code VARCHAR(60) UNIQUE NOT NULL,issued_on DATE,FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE);
